const SZE = 24, NUM = 10;
let pal;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("grid of colored circles distributing around the equator");
	frameRate(60);
	pixelDensity(1);

	pal = [...random(palettes)].map((x) => x+"10");
	background(random(pal));
	background("#fefefe");
	// background("#101010");
	noStroke();
	ellipseMode(CENTER); // https://p5js.org/reference/p5/ellipseMode/

	loop();
}

function draw() {
	// grid
	if (true) {
		// stroke(0);
		for (let y = SZE/2; y < height; y+=SZE) {
			beginShape();
			for (let x = SZE/2; x < width; x+=SZE) {
				const pos = getPos(x, y);
				// vertex(pos.x, pos.y);

				const dst = abs((y/height - 0.5) * 2);
				if (dst < random()) {
					fill(random(pal));
					const f = random(0.6, 0.9);
					mCircle(pos.x, pos.y, SZE * f);
				}
			}
			endShape();
		}
		// noLoop() removed for animation
	}

	// random positions, overdrawing positions with other colors possible
	if (false) {
		for (let i = 0; i < NUM; i++) {		
			const x = ~~(random(width) / SZE) * SZE + SZE/2;
			const y = ~~(random(height) / SZE) * SZE + SZE/2;

			var dst = abs((y/height - 0.5) * 2);
			if (dst < random()) {
				fill(random(pal));
				var pos = getPos(x, y);
				var f = random(0.8, 1.1);
				// ellipse(pos.x, pos.y, SZE*f, SZE*f);
				mCircle(pos.x, pos.y, SZE * f);
			}
		}
	}
}

function mCircle(x, y, d) {
	// circle(x, y, d);
	const dlt = d/10 * random(0.15, 1); // reduce bluriness per each randomly
	for (let i = 0; i < 20; i++) {
		const cx = x + random(-dlt, dlt);
		const cy = y + random(-dlt, dlt);
		const dx = d - random(dlt*2);
		const dy = d - random(dlt*2);
		// ellipse(cx, cy, dx, dy);
		push()
		translate(cx, cy);
		rotate(random(PI));
		ellipse(0, 0, dx, dy);
		pop()
	}
}

function getPos(x, y) {
	var dx = (noise(x/SZE, y/SZE) - 0.5) * SZE;
	var dy = (noise(y/SZE, x/SZE) - 0.5) * SZE;
	return {x: x + dx, y: y + dy};
}

function mouseClicked() {
	if (mouseButton != RIGHT && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > width*0.1 && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < width*0.9) setup();
}
